_default = 'DEFAULT'


class AttenuatorTypes(object):
    def __init__(self, attenuator_types):
        if isinstance(attenuator_types, dict):
            self.available_types = attenuator_types
        else:
            self.available_types = {_default: attenuator_types}

    def __getitem__(self, item):
        try:
            if item:
                item = item.upper()
            else:
                item = _default
            attenuator_type = self.available_types[item]
            return attenuator_type
        except KeyError:
            raise AttenuatorTypeNotSupported(
                '{} is not supported'.format(item))


